function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('[data-widget_type="price-list.default"]').each(function () {
    const $ul = $(this).find('ul.elementor-price-list');
    if (!$ul.length) return;

    const $wrap = $ul.closest('.elementor-widget-wrap');
    let section = null;
    const $headingWidget = $wrap.prevAll('[data-widget_type="heading.default"]').first();
    if ($headingWidget.length) {
      const headingText = $headingWidget.find('.elementor-heading-title').text().trim();
      section = cleanText(headingText) || null;
    }

    $ul.find('li.elementor-price-list-item').each(function () {
      const $title = $(this).find('.elementor-price-list-title');
      const nameRaw = $title.text();
      const name = cleanText(nameRaw);
      if (!name) return;

      const $price = $(this).find('.elementor-price-list-price');
      const price = parsePrice($price.text());

      const $desc = $(this).find('.elementor-price-list-description');
      const descriptionRaw = $desc.text();
      const description = descriptionRaw ? cleanText(descriptionRaw) : null;

      const key = `${section}|${name}|${description}|${price}`;
      if (seen.has(key)) return;
      seen.add(key);
      items.push({ section, name, description, price });
    });
  });

  return items;
}
